import csv
import json
import subprocess
import re

def mcp_call(method, params):
    cmd = ['mcp-tool', 'call', 'google-cloud', method, json.dumps(params)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    output = result.stdout
    full_marker = '__FULL_RESULTS_JSON__'
    if full_marker in output:
        idx = output.index(full_marker)
        output = output[idx + len(full_marker):].strip()
    if '{' not in output:
        return None
    try:
        return json.loads(output)
    except json.JSONDecodeError:
        return None

# Step 1: Query BigQuery for all historical scores and compute averages
union_tables = ' UNION ALL '.join([
    f'SELECT student_id, name, score FROM academic_warning.scores_250{i}'
    for i in range(1, 8)
])
query = f"SELECT student_id, name, AVG(score) as avg_score FROM ({union_tables}) GROUP BY student_id, name"
print("Running BigQuery union of 7 tables...")
result = mcp_call('bigquery_run_query', {'query': query})

avg_scores = {}
for row in result['rows']:
    sid = row['student_id']
    avg_scores[sid] = {'name': row['name'], 'avg_score': row['avg_score']}
print(f"Loaded {len(avg_scores)} students from historical data")

# Step 2: Read latest quiz scores
latest_scores = {}
with open('/app/latest_quiz_scores.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        sid = row['student_id']
        latest_scores[sid] = {'name': row['name'], 'score': float(row['score'])}
print(f"Loaded {len(latest_scores)} latest scores")

# Step 3: Calculate drops
drop_25 = []
drop_45 = []
for sid in latest_scores:
    latest = latest_scores[sid]['score']
    if sid in avg_scores:
        avg = avg_scores[sid]['avg_score']
        if avg > 0:
            drop_pct = (avg - latest) / avg * 100
            name = latest_scores[sid]['name']
            if drop_pct > 25:
                drop_25.append((sid, name, avg, latest, drop_pct))
            if drop_pct > 45:
                drop_45.append((sid, name, avg, latest, drop_pct))

print(f"Students with >25% drop: {len(drop_25)}")
print(f"Students with >45% drop: {len(drop_45)}")

# Step 4: Write bad_student.csv
with open('/app/bad_student.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['student_id', 'name', 'average_score', 'latest_score', 'drop_percentage'])
    for sid, name, avg, latest, drop_pct in sorted(drop_25, key=lambda x: -x[4]):
        writer.writerow([sid, name, round(avg, 2), round(latest, 2), round(drop_pct, 2)])
print(f"Wrote {len(drop_25)} students to bad_student.csv")

# Step 5: Write critical warning logs for >45% drop students
log_bucket = 'exam_log-b711e7743e03'
for sid, name, avg, latest, drop_pct in sorted(drop_45, key=lambda x: -x[4]):
    log_entry = f"CRITICAL ALERT: Student {name} (ID: {sid}) has experienced a severe academic warning. Score dropped from {round(avg, 2)} to {round(latest, 2)} ({round(drop_pct, 2)}% decrease). Immediate counselor notification required."
    print(f"Writing critical log for {name} ({sid}): drop {round(drop_pct, 2)}%")
    params = {
        'log_name': log_bucket,
        'message': log_entry,
        'severity': 'CRITICAL'
    }
    r = mcp_call('logging_write_log', params)
    if r:
        print(f"  -> Log written successfully")

print("\nDone!")
PYEOF
